import{_ as t,o as a,c as r,a2 as l}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Rules & labels","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/rules.md","filePath":"en/guide/rules.md"}'),o={name:"en/guide/rules.md"};function s(n,e,i,d,h,u){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="rules-labels" tabindex="-1">Rules &amp; labels <a class="header-anchor" href="#rules-labels" aria-label="Permalink to &quot;Rules &amp; labels&quot;">​</a></h1><p>The <strong>Rules &amp; labels</strong> page (<code>/rules</code>) automates sorting your mailbox: each rule applies an action to the mails it matches. It has two tabs: <strong>Rules</strong> and <strong>Labels</strong> (<code>/rules?tab=labels</code>).</p><hr><h2 id="rules-tab" tabindex="-1">Rules tab <a class="header-anchor" href="#rules-tab" aria-label="Permalink to &quot;Rules tab&quot;">​</a></h2><p>The list shows for each rule:</p><ul><li><strong>Name</strong>;</li><li><strong>Conditions</strong>, in plain words (&quot;from <a href="mailto:news@example.com" target="_blank" rel="noreferrer">news@example.com</a>, older than 30 days&quot;);</li><li><strong>Action</strong> (&quot;Apply a label “Invoices”&quot;…);</li><li><strong>Last run</strong> (or &quot;Never run&quot;);</li><li><strong>Active</strong>: a switch to pause or resume the rule.</li></ul><p>A rule&#39;s <code>⋯</code> menu offers:</p><ul><li><strong>Run</strong>: runs the rule now on mails already received. A toast &quot;Running “…”&quot; lets you <strong>Undo</strong> for 10 s; follow the rest in <a href="./activity.html">Activity</a>.</li><li><strong>Edit</strong>: opens the form.</li><li><strong>Delete</strong>: after confirmation (&quot;The rule will not run anymore. Mails it already handled stay as they are.&quot;).</li></ul><p>With no rule, the page suggests creating one or starting from a template in the Labels tab.</p><hr><h2 id="create-a-rule" tabindex="-1">Create a rule <a class="header-anchor" href="#create-a-rule" aria-label="Permalink to &quot;Create a rule&quot;">​</a></h2><p>The <strong>New rule</strong> button (also in the <code>⌘K</code> palette) opens the form. It also opens prefilled from:</p><ul><li><a href="./mails.html">Mail</a>: <strong>Create a rule</strong> in the header (current search), the selection bar or the reader;</li><li><a href="./cleanup.html">Cleanup</a> and the <a href="./overview.html">Overview</a> suggestions: <strong>Always do this</strong>;</li><li>the Labels tab: <strong>Create a rule</strong> on a label.</li></ul><h3 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Content</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>suggested automatically (&quot;Mails from …&quot;)</td></tr><tr><td><strong>When a mail comes from</strong></td><td>address or domain, e.g. <code>news@example.com</code></td></tr><tr><td><strong>Other conditions (kept)</strong></td><td>conditions of an existing rule that the form cannot edit; they are kept as they are</td></tr><tr><td><strong>And is older than</strong></td><td>No limit, 7 days, 30 days, 6 months</td></tr><tr><td><strong>Then</strong></td><td>Save to the NAS then delete · Archive (remove from inbox) · Delete · Apply a label (+ pick the <strong>Label</strong>)</td></tr><tr><td><strong>Runs</strong></td><td>Manual, Daily (default), Weekly</td></tr><tr><td><strong>Also apply to mails already received</strong></td><td>runs the rule as soon as it is saved (with the same undo toast)</td></tr></tbody></table><p>A sender is required: &quot;a rule based on age alone would target the whole mailbox&quot;.</p><h3 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h3><p>Under the form, Nid computes the matching mails: &quot;143 matching mails · 58 MB&quot;, a few <strong>Examples</strong>, and the <strong>See the 143 mails</strong> link, which opens <a href="./mails.html">Mail</a> with the matching search.</p><p><strong>Create rule</strong> (or <strong>Save</strong> when editing) confirms.</p><hr><h2 id="labels-tab" tabindex="-1">Labels tab <a class="header-anchor" href="#labels-tab" aria-label="Permalink to &quot;Labels tab&quot;">​</a></h2><p>&quot;Your Gmail labels, synced with their colors, and ready-made templates.&quot;</p><h3 id="gmail-labels" tabindex="-1">Gmail labels <a class="header-anchor" href="#gmail-labels" aria-label="Permalink to &quot;Gmail labels&quot;">​</a></h3><p>The account&#39;s label tree, with their Gmail color and the number of archived mails. Nested labels (<code>Invoices/Power</code>) show as a tree.</p><ul><li><strong>New label</strong>: creates the label in Gmail. Use &quot;/&quot; to nest it, e.g. <code>Invoices/Power</code>.</li><li>A label&#39;s menu: <ul><li><strong>Rename</strong>;</li><li><strong>Color</strong> (Gmail palette: Red, Orange, Yellow, Green, Teal, Blue, Purple, Pink, Gray);</li><li><strong>Create a rule</strong> that applies this label;</li><li><strong>See mails</strong>: opens <a href="./mails.html">Mail</a> filtered on this label;</li><li><strong>Delete</strong>: after confirmation; the label is removed from Gmail and from the mails that have it, the mails are not deleted.</li></ul></li></ul><h3 id="gmail-categories" tabindex="-1">Gmail categories <a class="header-anchor" href="#gmail-categories" aria-label="Permalink to &quot;Gmail categories&quot;">​</a></h3><p>Promotions, Social, Updates, Forums: &quot;Assigned by Gmail, cannot be changed.&quot;</p><h3 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h3><p>&quot;One click creates the Gmail label and the rule that fills it.&quot;</p><ul><li>Labels: <strong>Factures</strong> (invoices), <strong>Livraisons</strong> (deliveries), <strong>Banque</strong> (bank), <strong>Billets &amp; voyages</strong> (tickets &amp; travel) — each template creates the label and a daily rule that applies it based on subject keywords (button <strong>Create label and rule</strong>). Template names come from the server and are in French.</li><li>Expiry: <strong>Codes OTP (expire après 1 jour)</strong>, <strong>Promotions (expire après 7 jours)</strong> — a rule that deletes those mails once they are older than the age (button <strong>Activate</strong>). These templates replace the former &quot;Email expiration&quot; page.</li><li><strong>Other templates</strong>: cleanup (GitHub notifications, unread newsletters, promotions, social), archiving (old mails, invoices, large mails) and organizing (mark old mails as read…), button <strong>Activate</strong>.</li></ul><p>A template already in use shows <strong>Already active</strong> and the <strong>Edit rule</strong> button.</p>',31)])])}const c=t(o,[["render",s]]);export{m as __pageData,c as default};
